use bend2_lsp::analysis::{self, CompletionKind, DocumentSnapshot, Revision};

fn main() {
    let source = "type T is Data:\n  C{}\ndef C() -> U32:\n  0\n";
    let snapshot = DocumentSnapshot::new(Revision(1), source.to_owned());
    for prefix in ["C", "c"] {
        let values = analysis::module_completion_items(&snapshot, prefix);
        let constructors = analysis::constructor_completion_items(&snapshot, None, prefix);
        assert_eq!(values.iter().map(|item| (item.label.as_str(), item.kind)).collect::<Vec<_>>(), [("C", CompletionKind::Function)]);
        assert_eq!(constructors.iter().map(|item| (item.label.as_str(), item.kind)).collect::<Vec<_>>(), [("C", CompletionKind::Constructor)]);
    }
    let recovery = concat!(
        "type Ns.First is Data:\n  Ns.HiddenA{}\n  Ns.HiddenB{}\n",
        "def Ns.middle() -> U32:\n  0\n",
        "type Ns.Empty is Data:\n",
        "type Ns.Last is Data:\n  Ns.Unfinished{field:",
    );
    let snapshot = DocumentSnapshot::new(Revision(2), recovery.to_owned());
    assert_eq!(analysis::module_completion_items(&snapshot, "Ns.").iter().map(|item| item.label.as_str()).collect::<Vec<_>>(), ["Ns.First", "Ns.middle", "Ns.Empty", "Ns.Last"]);
    assert_eq!(analysis::module_completion_items(&snapshot, "Ns.H"), []);
    assert_eq!(analysis::constructor_completion_items(&snapshot, None, "Ns.H").iter().map(|item| item.label.as_str()).collect::<Vec<_>>(), ["Ns.HiddenA", "Ns.HiddenB", "Ns.Unfinished"]);
    println!("completion API smoke passed: same-spelling value/constructor meanings, ASCII case, constructor-only prefix exclusion, and malformed-input source order");
}
